const ownerLogin = 'hsimah';
const forgejoApiBaseUrl = 'https://kennl.loft.hsimah.com/api/v1';

const labelEvent = $input.first().json.body ?? {};
const issue = labelEvent.issue ?? {};
const labelNames = (issue.labels ?? []).map((label) => label.name);

const isReadyLabelEventFromOwner =
  labelEvent.action === 'label_updated' &&
  !issue.pull_request &&
  issue.state === 'open' &&
  labelNames.includes('agent:ready') &&
  !labelNames.includes('agent:working') &&
  labelEvent.sender?.login === ownerLogin &&
  issue.user?.login === ownerLogin;

if (!isReadyLabelEventFromOwner) {
  return [];
}

return [
  {
    json: {
      ownerLogin,
      forgejoApiBaseUrl,
      repositoryFullName: labelEvent.repository.full_name,
      issueNumber: issue.number,
      branchName: `claude/issue-${issue.number}`,
    },
  },
];

const labelEvent = $('Read label event').first().json;
const issue = $('Get issue').first().json;
const recentTimelineEvents = $input.all().map((item) => item.json);
const currentLabelNames = (issue.labels ?? []).map((label) => label.name);

const latestReadyLabelEvent = recentTimelineEvents
  .filter((timelineEvent) => timelineEvent.type === 'label' && timelineEvent.label?.name === 'agent:ready')
  .at(-1);
const latestReadyLabeller = latestReadyLabelEvent?.user?.login;

const gateFailures = [];
if (issue.state !== 'open') {
  gateFailures.push('issue is not open');
}
if (issue.user?.login !== labelEvent.ownerLogin) {
  gateFailures.push(`issue was written by ${issue.user?.login}`);
}
if (!currentLabelNames.includes('agent:ready')) {
  gateFailures.push('agent:ready is no longer on the issue');
}
if (currentLabelNames.includes('agent:working')) {
  gateFailures.push('issue is already being worked on');
}
if (latestReadyLabeller !== labelEvent.ownerLogin) {
  gateFailures.push(`agent:ready was last added by ${latestReadyLabeller ?? 'nobody in the last 15 minutes'}`);
}

if (gateFailures.length > 0) {
  console.log(`Gate stopped #${labelEvent.issueNumber}: ${gateFailures.join('; ')}`);
  return [];
}

return [
  {
    json: {
      ...labelEvent,
      issueTitle: issue.title,
      issueBody: issue.body ?? '',
      claimedLabelNames: [...currentLabelNames.filter((labelName) => labelName !== 'agent:ready'), 'agent:working'],
    },
  },
];

const gatePassed = $('Check gate').first().json;
const labelsAfterClaim = $input.all().map((item) => item.json);
const workingLabel = labelsAfterClaim.find((label) => label.name === 'agent:working');

if (!workingLabel) {
  throw new Error('agent:working was not applied to the issue. Check the label exists in the organisation.');
}

const implementPrompt = `Implement issue #${gatePassed.issueNumber} in ${gatePassed.repositoryFullName}.
Follow CLAUDE.md if the repository has one. The issue below is the whole task.

<issue>
Title: ${gatePassed.issueTitle}

${gatePassed.issueBody}
</issue>

Make the smallest change that satisfies the issue. Only edit files: the repository's .git is read-only,
and the host commits and pushes your changes when you finish.

When you are finished, reply with ONLY one JSON object and nothing else:
{"status": "done", "commit_message": "<type>: <summary>\\n\\n<what changed and how you checked it>"}

If the issue is ambiguous, or too large for one small change, change nothing and reply with ONLY:
{"status": "needs-human", "reason": "<what is missing or unclear>"}`;

const encodedPrompt = Buffer.from(implementPrompt, 'utf8').toString('base64');
const maximumEncodedPromptLength = 100000;
if (encodedPrompt.length > maximumEncodedPromptLength) {
  throw new Error(`Issue #${gatePassed.issueNumber} is too long to send (${encodedPrompt.length} base64 characters).`);
}

return [
  {
    json: {
      ...gatePassed,
      workingLabelId: workingLabel.id,
      sshCommand: `implement ${gatePassed.repositoryFullName} ${gatePassed.branchName} ${encodedPrompt}`,
    },
  },
];

const implementRequest = $('Build implement request').first().json;
const sshOutput = $input.first().json;

let runResult;
try {
  runResult = JSON.parse(sshOutput.stdout);
} catch {
  const sshFailureDetail = sshOutput.stderr || sshOutput.error?.message || sshOutput.message || 'no output from rodnik';
  runResult = { is_error: true, outcome: 'ssh-error', reason: String(sshFailureDetail).slice(0, 2000) };
}

let commitMessage = '';
try {
  const resultWithoutFences = String(runResult.result ?? '').replace(/^\s*```.*$/gm, '');
  commitMessage = JSON.parse(resultWithoutFences).commit_message ?? '';
} catch {
  commitMessage = '';
}

const [commitSubject = '', ...commitBodyLines] = commitMessage.split('\n');
const commitBodyWithoutClosingLines = commitBodyLines
  .filter((line) => !/^\s*(closes|fixes|resolves)\s+#\d+\s*$/i.test(line))
  .join('\n')
  .trim();
const shortPushedCommit = (runResult.pushed_commit ?? '').slice(0, 7);

const pullRequestTitle = commitSubject.trim() || `Implement #${implementRequest.issueNumber}: ${implementRequest.issueTitle}`;
const pullRequestBody = [
  `Closes #${implementRequest.issueNumber}`,
  commitBodyWithoutClosingLines,
  `---\nImplemented by Claude on rodnik (\`${shortPushedCommit}\`).`,
]
  .filter(Boolean)
  .join('\n\n');

const wasRejectedBeforeClaudeRan = runResult.outcome === 'rejected';
const failureReason = runResult.reason ?? (wasRejectedBeforeClaudeRan ? runResult.result : '') ?? '';
const claudeOutputExcerpt =
  !wasRejectedBeforeClaudeRan && runResult.outcome !== 'needs-human' && runResult.result
    ? `<details><summary>Claude's final message</summary>\n\n\`\`\`\n${String(runResult.result).slice(0, 4000)}\n\`\`\`\n</details>`
    : '';
const failureComment = [
  `Agent work stopped: **${runResult.outcome ?? 'unknown'}**.`,
  failureReason,
  claudeOutputExcerpt,
  'Update the issue or fix the setup, then add `agent:ready` again to retry.',
]
  .filter(Boolean)
  .join('\n\n');

return [
  {
    json: {
      ...implementRequest,
      outcome: runResult.outcome ?? 'unknown',
      wasPushed: runResult.outcome === 'pushed',
      baseBranch: runResult.base_branch,
      pullRequestTitle,
      pullRequestBody,
      failureComment,
    },
  },
];
